using System;using System.Collections.Generic;public class Solution{int G(int a,int b){a=Math.Abs(a);b=Math.Abs(b);while(b!=0){int t=a%b;a=b;b=t;}return a;}public int MaxPoints(int[][]p){int best=0;for(int i=0;i<p.Length;i++){var m=new Dictionary<(int,int),int>();int dup=1,local=0;for(int j=i+1;j<p.Length;j++){int dx=p[j][0]-p[i][0],dy=p[j][1]-p[i][1];if(dx==0&&dy==0){dup++;continue;}int z=G(dx,dy);dx/=z;dy/=z;if(dx<0||dx==0&&dy<0){dx=-dx;dy=-dy;}var k=(dx,dy);m[k]=m.GetValueOrDefault(k)+1;local=Math.Max(local,m[k]);}best=Math.Max(best,local+dup);}return best;}}
